export function* allOf(validator, value, instance, schema) {
  for (const subschema of value) {
    yield* validator.descend(instance, subschema, null);
  }
}

export function* anyOf(validator, value, instance, schema) {
  for (const subschema of value) {
    if (validator.isValidAgainst(instance, subschema)) {
      return;
    }
  }
  yield new validator.ValidationError(
    `${JSON.stringify(instance)} is not valid under any of the given schemas`,
  );
}

export function* oneOf(validator, value, instance, schema) {
  const valids = [];
  for (let index = 0; index < value.length; index++) {
    if (validator.isValidAgainst(instance, value[index])) {
      valids.push(index);
    }
  }
  if (valids.length !== 1) {
    yield new validator.ValidationError(
      `${JSON.stringify(instance)} is valid under each of ${valids.join(", ")}`,
    );
  }
}

export function* not(validator, value, instance, schema) {
  if (validator.isValidAgainst(instance, value)) {
    yield new validator.ValidationError(
      `${JSON.stringify(instance)} should not be valid under the given schema`,
    );
  }
}

export function* if_(validator, value, instance, schema) {
  if (validator.isValidAgainst(instance, value)) {
    if (Object.prototype.hasOwnProperty.call(schema, "then")) {
      yield* validator.descend(instance, schema.then, null);
    }
  } else {
    if (Object.prototype.hasOwnProperty.call(schema, "else")) {
      yield* validator.descend(instance, schema.else, null);
    }
  }
}

