// Error types mirroring jsonschema's ValidationError / SchemaError surface
// that the translated program relies on.

export class ValidationError {
  constructor(message) {
    this.message = message;
    // Absolute path within the instance (filled in by the validator as the
    // error bubbles up through keyword validators).
    this.path = [];
    // Relative schema path (keyword chain), informational only.
    this.schemaPath = [];
    // Set by the validator loop as the error bubbles up:
    this.validator = undefined;
    this.validatorValue = undefined;
    this.instance = undefined;
    this.schema = undefined;
    // Sub-errors (e.g. for anyOf/oneOf), informational only.
    this.context = [];
  }
}

export class SchemaError extends Error {
  constructor(message, errors = []) {
    super(message);
    this.name = 'SchemaError';
    this.errors = errors;
  }
}
